<?php $articleSections=$article['sections'] ?? []; $toc=array_filter($articleSections,static fn(array $s):bool=>trim($s['heading'])!==''); ?>
<article class="article-page"><header class="article-hero"><div class="container container--md"><div class="breadcrumb"><a href="/articles"><?= e(t('nav.articles')) ?></a><span><?= icon('arrow-left') ?></span><span><?= e($article['type']) ?></span></div><span class="eyebrow">دفتر یادگیری منتوریس</span><h1><?= e($article['title']) ?></h1><p><?= e($article['excerpt']) ?></p><div class="article-meta"><?php if(!empty($article['author_slug'])): ?><a class="article-author-chip" href="/mentors/<?= e($article['author_slug']) ?>"><?php if(!empty($authorMentor['image'])): ?><img src="<?= asset($authorMentor['image']) ?>" width="48" height="48" alt="<?= e($article['author']) ?>"><?php endif; ?><?= e($article['author']) ?></a><?php else: ?><span><?= icon('user') ?> <?= e($article['author']) ?></span><?php endif; ?><span><?= icon('clock') ?> <?= e($article['read']) ?></span><time datetime="<?= e(substr($article['published_at'],0,10)) ?>"><?= e(substr($article['published_at'],0,10)) ?></time></div><?php if(!empty($article['credit'])): ?><small><?= e($article['credit']) ?></small><?php endif; ?></div></header>
<?php if(!empty($article['image'])): ?><figure class="container container--md article-cover"><img src="<?= asset($article['image']) ?>" alt="<?= e($article['title']) ?>" width="1536" height="1024"><figcaption>یادگیری، تمرین، بازخورد؛ قدم‌های یک مسیر حرفه‌ای.</figcaption></figure><?php endif; ?>
<?php if(!empty($article['key_points'])): ?><aside class="container container--md article-takeaways"><span class="eyebrow">سه نکته برای همراه‌بردن</span><div><?php foreach($article['key_points'] as $index=>$point): ?><p><span><?= str_pad((string)($index+1),2,'0',STR_PAD_LEFT) ?></span><?= e($point) ?></p><?php endforeach; ?></div></aside><?php endif; ?>
<?php if($toc): ?><nav class="container container--sm article-toc" aria-label="فهرست مقاله"><strong>در این یادداشت</strong><ol><?php foreach($articleSections as $index=>$section): if(trim($section['heading'])==='') continue; ?><li><a href="#section-<?= $index+1 ?>"><?= e($section['heading']) ?></a></li><?php endforeach; ?></ol></nav><?php endif; ?>
<div class="container container--sm article-body"><?php if($articleSections): foreach($articleSections as $index=>$section): ?><section id="section-<?= $index+1 ?>"><?php if(trim($section['heading'])!==''): ?><h2><?= e($section['heading']) ?></h2><?php endif; ?><?php foreach(preg_split('/\n\s*\n/u',$section['body']) ?: [] as $paragraph): if(trim($paragraph)==='') continue; ?><p><?= nl2br(e(trim($paragraph))) ?></p><?php endforeach; ?></section><?php endforeach; else: foreach(preg_split('/\n\s*\n/u',(string)$article['body']) ?: [] as $paragraph): if(trim($paragraph)==='') continue; ?><p><?= nl2br(e(trim($paragraph))) ?></p><?php endforeach; endif; ?></div></article>
<?php if(!empty($article['references'])): ?><aside class="container container--sm article-sources"><h2>منابع این یادداشت</h2><ol><?php foreach($article['references'] as [$label,$url]): ?><li><a href="<?= e($url) ?>" target="_blank" rel="noopener noreferrer"><?= e($label) ?> <?= icon('arrow-up-left') ?></a></li><?php endforeach; ?></ol></aside><?php endif; ?>
<section class="container container--md article-bridge"><div><span class="eyebrow">از خواندن به تمرین</span><h2>یک مهارت کوچک، یک قدم قابل مشاهده</h2><p>در کارگاه‌ها و حلقه‌های منتوریس، مسیر رشد حرفه‌ای را با گفت‌وگو، تمرین و بازخورد دنبال کنید.</p><?php if(!empty($article['related_course'])): ?><a class="btn btn--primary" href="/courses/<?= e($article['related_course']) ?>">کارگاه تمرین عامدانه <?= icon('arrow-left') ?></a><?php else: ?><a class="btn btn--primary" href="/events">آشنایی با حلقه‌های درمانگران</a><?php endif; ?></div></section>
<?php if(!empty($relatedArticles)): ?><section class="section article-related"><div class="container"><header class="section__head"><h2>در همین مسیر بیشتر بخوانید</h2><a href="/articles" class="btn btn--secondary">همه مقاله‌ها</a></header><div class="grid grid--3 articles-grid"><?php foreach($relatedArticles as $article): require view_path('components/cards/article-card.php'); endforeach; ?></div></div></section><?php endif; ?>
